import re

def parse_duration(s):
    """Convert a human duration string to a whole number of seconds. See spec.md."""
    if not isinstance(s, str):
        raise ValueError("Input must be a string")

    s = s.strip()
    if not s:
        raise ValueError("Empty string")

    # Try colon form first: hh:mm:ss or mm:ss
    if ':' in s:
        return _parse_colon(s)

    # Try unit-based form: e.g., "1h30m15s", "1.5h", "90s", "90"
    return _parse_units(s)


def _parse_colon(s):
    """Parse colon-separated time: mm:ss or hh:mm:ss"""
    parts = s.split(':')
    if len(parts) == 2:
        # mm:ss
        try:
            minutes = int(parts[0])
            seconds = int(parts[1])
        except ValueError:
            raise ValueError(f"Invalid colon format: {s!r}")
        if minutes < 0 or seconds < 0:
            raise ValueError(f"Negative values not allowed: {s!r}")
        if seconds >= 60:
            raise ValueError(f"Seconds must be < 60 in mm:ss: {s!r}")
        return minutes * 60 + seconds
    elif len(parts) == 3:
        # hh:mm:ss
        try:
            hours = int(parts[0])
            minutes = int(parts[1])
            seconds = int(parts[2])
        except ValueError:
            raise ValueError(f"Invalid colon format: {s!r}")
        if hours < 0 or minutes < 0 or seconds < 0:
            raise ValueError(f"Negative values not allowed: {s!r}")
        if minutes >= 60 or seconds >= 60:
            raise ValueError(f"Minutes and seconds must be < 60 in hh:mm:ss: {s!r}")
        return hours * 3600 + minutes * 60 + seconds
    else:
        raise ValueError(f"Invalid colon format: {s!r}")


def _parse_units(s):
    """Parse unit-based duration: e.g., '1h30m15s', '1.5h', '90s', '90'"""
    # Pattern: optional number (int or float) followed by optional unit letter (h/m/s)
    # Units must be in order: h, then m, then s, each appearing at most once
    pattern = r'^(\d+(?:\.\d+)?)([hmsHMS])?$'

    # First check if it's a simple single value (bare number or number+unit)
    m = re.fullmatch(pattern, s)
    if m:
        num_str = m.group(1)
        unit = m.group(2)
        if unit is None:
            # Bare number = seconds
            try:
                val = float(num_str)
            except ValueError:
                raise ValueError(f"Invalid number: {s!r}")
            return int(val)
        else:
            unit = unit.lower()
            val = float(num_str)
            if unit == 's':
                return int(val)
            elif unit == 'm':
                return int(val * 60)
            elif unit == 'h':
                return int(val * 3600)

    # Multi-unit form: e.g., "1h30m", "1h30m15s", "2m30s"
    # Units must appear in order h, m, s, each at most once
    # Pattern: (num)(unit) repeated, with units in order
    multi_pattern = r'^(\d+(?:\.\d+)?)([hmsHMS])(\d+(?:\.\d+)?)([hmsHMS])(?:(\d+(?:\.\d+)?)([hmsHMS]))?$'
    m = re.fullmatch(multi_pattern, s)
    if m:
        groups = m.groups()
        # groups: (num1, unit1, num2, unit2, num3, unit3) where num3/unit3 may be None
        units_seen = set()
        total_seconds = 0.0
        prev_unit_rank = -1  # h=0, m=1, s=2

        for i in range(0, len(groups), 2):
            num_str = groups[i]
            unit = groups[i+1]
            if num_str is None or unit is None:
                break
            unit = unit.lower()
            if unit in units_seen:
                raise ValueError(f"Duplicate unit {unit!r} in {s!r}")
            units_seen.add(unit)

            unit_rank = {'h': 0, 'm': 1, 's': 2}[unit]
            if unit_rank <= prev_unit_rank:
                raise ValueError(f"Units out of order in {s!r}")
            prev_unit_rank = unit_rank

            val = float(num_str)
            if unit == 'h':
                total_seconds += val * 3600
            elif unit == 'm':
                total_seconds += val * 60
            elif unit == 's':
                total_seconds += val

        return int(total_seconds)

    # If nothing matched, it's invalid
    raise ValueError(f"Invalid duration: {s!r}")

